// Set search parameters
const today = new Date();
const yesterday = new Date(today);
yesterday.setDate(yesterday.getDate() - 1);

return [{
  json: {
    search_params: {
      locations: ['United States', 'Remote'],
      roles: ['Software Engineer', 'Data Scientist', 'Product Manager', 'Recruiter', 'HR Manager'],
      date_posted: 'last-24-hours',
      posted_after: yesterday.toISOString().split('T')[0],
      posted_before: today.toISOString().split('T')[0]
    },
    execution_date: today.toISOString(),
    report_date: today.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })
  }
}];

// Parse and normalize job data from all sources
const allItems = $input.all();
const normalizedJobs = [];

for (const item of allItems) {
  try {
    // Indeed format
    if (item.json.results) {
      item.json.results.forEach(job => {
        normalizedJobs.push({
          source: 'Indeed',
          company_name: job.company,
          title: job.jobtitle,
          location: job.formattedLocation,
          url: job.url,
          posted_date: job.date,
          description_snippet: job.snippet
        });
      });
    }

    // LinkedIn format
    if (item.json.data) {
      item.json.data.forEach(job => {
        normalizedJobs.push({
          source: 'LinkedIn',
          company_name: job.company,
          title: job.title,
          location: job.location,
          url: job.link,
          posted_date: job.postedTime,
          description_snippet: job.description
        });
      });
    }

    // ZipRecruiter format
    if (item.json.jobs) {
      item.json.jobs.forEach(job => {
        normalizedJobs.push({
          source: 'ZipRecruiter',
          company_name: job.hiring_company?.name || 'Unknown',
          title: job.name,
          location: job.location,
          url: job.url,
          posted_date: job.posted_time,
          description_snippet: job.snippet
        });
      });
    }
  } catch (error) {
    console.error('Error parsing job source:', error.message);
  }
}

return normalizedJobs.map(job => ({ json: job }));

// Compare to yesterday and identify truly new postings
const todayJobs = $('Normalize Job Data').all().map(item => item.json);
const yesterdayJobs = $input.all().map(item => item.json);

// Create set of yesterday job identifiers
const yesterdayIds = new Set(
  yesterdayJobs.map(j => `${j.company_name}|${j.title}|${j.location}`)
);

// Filter for new jobs not in yesterday's data
const newJobs = todayJobs.filter(job => {
  const jobId = `${job.company_name}|${job.title}|${job.location}`;
  return !yesterdayIds.has(jobId);
});

return [{
  json: {
    total_jobs_today: todayJobs.length,
    new_jobs: newJobs,
    new_jobs_count: newJobs.length
  }
}];

// Group jobs by company and calculate urgency scores
const newJobs = $input.first().json.new_jobs;

const jobsByCompany = {};
newJobs.forEach(job => {
  const company = job.company_name;
  if (!jobsByCompany[company]) {
    jobsByCompany[company] = [];
  }
  jobsByCompany[company].push(job);
});

// Calculate urgency score
function calculateUrgencyScore(jobs) {
  let score = jobs.length * 10;

  const seniorCount = jobs.filter(j => 
    /senior|lead|principal|director|vp|chief/i.test(j.title)
  ).length;
  score += seniorCount * 5;

  const techCount = jobs.filter(j =>
    /engineer|developer|architect|devops|scientist/i.test(j.title)
  ).length;
  score += techCount * 3;

  return score;
}

// Identify hot companies (5+ jobs)
const hotCompanies = Object.entries(jobsByCompany)
  .filter(([company, jobs]) => jobs.length >= 5)
  .map(([company, jobs]) => ({
    company_name: company,
    job_count: jobs.length,
    roles: jobs.map(j => j.title),
    locations: [...new Set(jobs.map(j => j.location))],
    urgency_score: calculateUrgencyScore(jobs),
    posted_date: jobs[0].posted_date
  }))
  .sort((a, b) => b.urgency_score - a.urgency_score);

return hotCompanies.map(company => ({ json: company }));

// Prepare market analysis data for GPT-4
const newJobs = $('Identify New Postings').first().json.new_jobs;
const hotCompanies = $('Flag Hot Companies (5+ Jobs)').all().map(item => item.json);

// Calculate top industries
const industries = {};
newJobs.forEach(job => {
  const title = job.title.toLowerCase();
  let industry = 'Other';

  if (/engineer|developer|software|tech/i.test(title)) industry = 'Technology';
  else if (/data|analyst|scientist/i.test(title)) industry = 'Data & Analytics';
  else if (/recruit|talent|hr|people/i.test(title)) industry = 'Human Resources';
  else if (/sales|account|business development/i.test(title)) industry = 'Sales';
  else if (/marketing|content|social/i.test(title)) industry = 'Marketing';

  industries[industry] = (industries[industry] || 0) + 1;
});

const topIndustries = Object.entries(industries)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([industry, count]) => `${industry} (${count})`);

// Calculate top locations
const locations = {};
newJobs.forEach(job => {
  const loc = job.location || 'Remote';
  locations[loc] = (locations[loc] || 0) + 1;
});

const topLocations = Object.entries(locations)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([loc, count]) => `${loc} (${count})`);

return [{
  json: {
    total_jobs: newJobs.length,
    hot_companies_count: hotCompanies.length,
    top_industries: topIndustries,
    top_locations: topLocations,
    hot_company_names: hotCompanies.slice(0, 10).map(c => c.company_name)
  }
}];

