// Format data for PDF report
const analysisData = $('Prepare Market Analysis Data').first().json;
const aiInsights = $input.first().json.choices?.[0]?.message?.content || 'AI insights unavailable - please review raw data.';
const hotCompanies = $('Find HR Contacts (Apollo.io)').all();

// Calculate role breakdown
const newJobs = $('Identify New Postings').first().json.new_jobs;
const roleBreakdown = {};
newJobs.forEach(job => {
  const title = job.title;
  roleBreakdown[title] = (roleBreakdown[title] || 0) + 1;
});

const topRoles = Object.entries(roleBreakdown)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([role, count]) => ({ role, count }));

// Format hot companies with HR contacts
const companiesWithContacts = hotCompanies.map(item => {
  const company = item.json;
  const hrContact = company.people?.[0] || {};

  return {
    company_name: company.company_name,
    job_count: company.job_count,
    urgency_score: company.urgency_score,
    roles: company.roles.slice(0, 5).join(', '),
    hr_contact_name: hrContact.name || 'Not found',
    hr_contact_email: hrContact.email || 'Not found',
    hr_contact_title: hrContact.title || ''
  };
});

return [{
  json: {
    report_date: $('Set Search Parameters').first().json.report_date,
    total_jobs: analysisData.total_jobs,
    hot_companies_count: hotCompanies.length,
    hr_contacts_found: companiesWithContacts.filter(c => c.hr_contact_email !== 'Not found').length,
    ai_insights: aiInsights,
    companies: companiesWithContacts,
    role_breakdown: topRoles,
    top_industries: analysisData.top_industries,
    top_locations: analysisData.top_locations
  }
}];

